def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return []
    names = []
    recipient_emails = []
    for item in data:
        if isinstance(item, dict):
            name = item.get('name', '')
            email = item.get('email', '')
            if name:
                names.append(name)
            if email:
                recipient_emails.append(email)
    if not names or not recipient_emails:
        return names
    body = 'Subject: Extracted Names\n\n' + '\n'.join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        server.sendmail(email_address, recipient_emails, body)
        server.quit()
    else:
        smtp.sendmail(email_address, recipient_emails, body)
    return names

