import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [process(item) for item in obj]
        elif obj is None:
            return REPLACE_NONE
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj
    data = json.loads(json_str)
    processed = process(data)
    def collect_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from collect_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from collect_values(item)
        else:
            yield obj
    value_counts = Counter(collect_values(processed))
    return {"data": processed, "value_counts": value_counts}

