import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    values = []
    def process(obj):
        if isinstance(obj, dict):
            to_delete = [k for k, v in obj.items() if v is None]
            for k in to_delete:
                del obj[k]
            for k, v in obj.items():
                if isinstance(v, str) and re.search(r'[\w\.-]+@[\w\.-]+\.\w+', v):
                    obj[k] = REPLACE_NONE
                else:
                    values.append(v)
                process(v)
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is not None:
                    if isinstance(item, str) and re.search(r'[\w\.-]+@[\w\.-]+\.\w+', item):
                        new_list.append(REPLACE_NONE)
                    else:
                        new_list.append(item)
                        values.append(item)
                process(item)
            obj[:] = new_list
    process(data)
    return {"data": data, "value_counts": Counter(values)}

