import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    for key in key_path:
        if isinstance(data, dict):
            if key not in data:
                raise KeyError(f"Key '{key}' not found.")
            data = data[key]
        else:
            raise KeyError(f"Key '{key}' not found.")

    if isinstance(data, str):
        if data.strip() == '':
            raise ValueError("The data string is empty.")
        try:
            nums = [float(x) for x in data.split(',') if x.strip()]
        except ValueError:
            raise ValueError("The data string is corrupted or contains non-numeric values.")
        if len(nums) == 0:
            raise ValueError("No numeric data found.")
    elif isinstance(data, list):
        nums = []
        for item in data:
            try:
                nums.append(float(item))
            except (ValueError, TypeError):
                raise ValueError("No numeric data found.")
        if len(nums) == 0:
            raise ValueError("No numeric data found.")
    else:
        raise ValueError("No numeric data found.")

    fig, ax = plt.subplots()
    sns.boxplot(data=nums, ax=ax)
    ax.set_title(f"Boxplot of data from key path: {'.'.join(key_path)}")
    return fig
